
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_ms2_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_ms2", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.682397964947678e+00, -4.589621938439342e+00, -4.459647332855965e+00, -4.279657581800635e+00, -4.034522011362596e+00, -3.708534410553766e+00, -3.289550448485912e+00, -2.776427965415741e+00, -2.188003066682795e+00, -1.549936108739642e+00, -9.936072413172943e-01, -6.856561108818127e-01, -6.050325854508750e-01, -5.167783952697286e-01, -3.642395972914754e-01, -2.194169981127845e-01, -1.138199026253855e-01, -4.140924826761262e-02, -9.015224520804352e-03, -1.013953113679651e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


